"""Registrar leituras e inspeção visual do lote B2-05 (registro 123)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json');N=len(m['paginas']);assert N==14
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)}
same_first={i for i in cur if ins['primeira_prova'][str(i)]==cur[i]};same_moved={i for i in range(10,15) if ins['mapa_reposicionado'][str(i)]==cur[i]}
again={4,8};assert same_first=={1,2,3,5,6,7,9},same_first;assert same_moved=={10,11,12,13,14}
method=lambda i:'Inspeção direta na primeira prova; imagem final idêntica (mesmo hash)' if i in same_first else 'Inspeção direta depois de reposicionar o mapa do pó; imagem final idêntica (mesmo hash)' if i in same_moved else 'Inspeção direta após o último ajuste'
notes={1:'Abertura das fichas e quadro largo dos três guardas, com linhas inteiras.',2:'Energia, Haru, espada e Fita; quadro das duas versões da Fita em largura inteira.',3:'Prende, aviso e intervalo, uso da técnica, Vigia e começo de Tessa com quadro dos feitiços.',4:'Prioridades de Tessa, golpe desarmado corrigido e quadro de Integridade. Espaço de fechamento do caso.',5:'Abertura do arquivo, tabela de posições e mapa novo com as duas versões lado a lado.',6:'Operar, forçar e conversar; uso do espaço; começo da comparação numérica.',7:'Quadro das composições e da Fita em largura inteira, legíveis.',8:'Socorro em passos numerados com Mei, Akira e Bao identificados; tabela da queda. Pequeno vazio antes do título largo.',9:'Fim da queda e registro para outro mestre. Espaço de fechamento do caso.',10:'Abertura do pó e mapa vetorial logo depois do primeiro parágrafo, sem vazio; preparo da área.',11:'Tabela de posições, exposição e ficha do perigo inteira, sem quebra.',12:'Contagem, duração, dano e condição, tabela de proteções e Concentração.',13:'Parar a máquina, romper o pino e quadro do exemplo em largura inteira.',14:'Queda a zero, socorro e tabela do que anotar.'}
save('revisao-final.json',{'registro':123,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das três fontes e das regras citadas, três cópias, remissões, clareza, a correção documentada do golpe de Tessa e a posição do painel.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura integral das catorze páginas da primeira prova e pente fino, incluindo frases da primeira passagem.'}],'ajuste_de_diagramacao':'Mapa do pó movido para depois da abertura do caso: na primeira prova deixava meia página vazia; no fim da seção de preparo, um terço.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':method(i),'observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Espaços de fechamento nas páginas 4 e 9 e pequeno vazio na 8 serão reavaliados na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s101':[1,4],'s102':[5,9],'s079':[10,14]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova_1':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':123,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':123,'lote':'B2-05','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':30,'casos_pendentes':29,'lotes_pendentes':7,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B2-06','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'revistas_apos_ajuste':sorted(again),'registros':len(changes),'casos':3},ensure_ascii=False))
